#!/usr/bin/env node
/**
 * bootstrap-group.js — generates a contingent local group fork from the CA regional core.
 *
 *   1. Validates group.json with validate-group-config.js (schema + anonymity + commercial-link blocks).
 *   2. Requires a real slug and an areaSlug that exists in the regional data (hub-and-spoke routing).
 *   3. Validates the regional data feeds (region/news/flyers) against their schemas.
 *   4. Renders platforms/ca-regional/templates/group/index.template.html with the group's meeting info,
 *      injected Organization + Event JSON-LD, and the inherited regional news, flyers, and conference card.
 *   5. Writes forks/<slug>/{index.html, group.json, group.jsonld.json, fork.manifest.json} atomically.
 *
 * Any failure exits 1 and writes nothing. Existing fork folders are replaced only if they carry a
 * fork.manifest.json (i.e. were generated by this script); hand-made folders are never overwritten.
 *
 * Usage: node scripts/bootstrap-group.js <group.json> [--out-root forks] [--check]
 *   --check  exit 1 if the committed fork differs from a fresh build (used in CI); writes nothing
 */
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { C, FORKS_DIR, HARNESS, REPO, SITE_DIR, assets, loadFeeds, meetingsForRuntime, sha256, template } from "./lib/site-kit.js";

export const GENERATOR_VERSION = "1.0.0";

function fail(errors) { return { ok: false, errors }; }

export function bootstrapGroup(groupFile, { outRoot = FORKS_DIR } = {}) {
  // 1. Harness validation (reuse the CLI so behavior and exit codes stay identical).
  const v = spawnSync(process.execPath, [HARNESS, groupFile], { encoding: "utf8" });
  if (v.status !== 0) return fail([`validate-group-config.js rejected ${groupFile} (exit ${v.status})`, ...v.stderr.split("\n").filter((l) => /ERROR/.test(l)).map((l) => l.replace(/^\s*ERROR\s*/, "").trim())]);
  let groupJsonLd;
  try { groupJsonLd = JSON.parse(v.stdout); } catch { return fail(["harness did not emit JSON-LD"]); }
  const rawCfg = readFileSync(groupFile, "utf8");
  const cfg = JSON.parse(rawCfg);

  // 2. Fork-specific requirements.
  const errors = [];
  if (!cfg.slug || C.isVerify(cfg.slug) || !/^[a-z0-9-]+$/.test(cfg.slug)) errors.push("slug is required for a fork (lowercase letters, digits, hyphens)");
  const { feeds, errors: feedErrors, hash: feedHash } = loadFeeds();
  errors.push(...feedErrors);
  const area = feeds.region?.areas?.find((a) => a.slug === cfg.areaSlug);
  if (!area) errors.push(`areaSlug "${cfg.areaSlug ?? "(missing)"}" must match an area in platforms/ca-regional/data/region.json (hub-and-spoke routing)`);
  if (!(cfg.meetings || []).some((m) => !C.isVerify(m.day) && !C.isVerify(m.time))) errors.push("at least one meeting needs a confirmed day and time to publish a fork");
  if (errors.length) return fail(errors);

  const { region, news, flyers } = feeds;
  const forkDir = join(outRoot, cfg.slug);
  const regionHref = relative(forkDir, join(SITE_DIR, "index.html")).split("\\").join("/");
  const areaHref = `${regionHref}#area-${area.slug}`;
  const loc = cfg.venueLocality || {};
  const m0 = cfg.meetings[0];
  const sum = C.meetingSummary(m0);
  const meetingsHtml = cfg.meetings.map((m) => {
    const s = C.meetingSummary(m);
    const online = m.attendance === "hybrid" || m.attendance === "online";
    const inPerson = m.attendance === "hybrid" || m.attendance === "in-person";
    return `<dl class="facts">
      <dt>When</dt><dd>Every ${C.esc(s.day)}, ${C.esc(s.time)} ${C.isVerify(m.timezone) ? C.badge("timezone") : `(${C.esc(m.timezone)})`}</dd>
      ${inPerson ? `<dt>Where</dt><dd>${C.esc(cfg.venueLabel)}${C.isVerify(loc.city) || !loc.city ? "" : `, ${C.esc(loc.city)}${loc.state && !C.isVerify(loc.state) ? `, ${C.esc(loc.state)}` : ""}`} ${cfg.venueAddress && !C.isVerify(cfg.venueAddress) ? `· ${C.esc(cfg.venueAddress)}` : C.badge("street address")}</dd>` : ""}
      ${online ? `<dt>Online</dt><dd>Zoom, at the same time ${C.isHttp(cfg.links?.onlineMeetingUrl) ? `<a href="${C.esc(cfg.links.onlineMeetingUrl)}">Join on Zoom</a>` : C.badge("Zoom link")}</dd>` : ""}
      <dt>Format</dt><dd>${m.format === "open" ? "Open meeting. Anyone can attend, including family and friends." : m.format === "closed" ? "Closed meeting, for people who want to stop using." : C.badge("format")} No pressure to speak.</dd>
      <dt>Cost</dt><dd>Free. No dues or fees. ${C.esc(C.isVerify(cfg.seventhTraditionNote) || !cfg.seventhTraditionNote ? "" : cfg.seventhTraditionNote)}</dd>
    </dl>`;
  }).join("\n");

  const fellowship = cfg.fellowship && !C.isVerify(cfg.fellowship) ? cfg.fellowship : region.fellowship;
  const meetings = meetingsForRuntime(cfg);
  const tagline = `${sum.day}s at ${sum.time}, ${sum.mode === "In-Person + Zoom" ? `in person at ${cfg.venueLabel} and on Zoom` : sum.mode === "Online" ? "online" : `in person at ${cfg.venueLabel}`}.`;
  const { css, js } = assets();
  const inheritedNote = `Inherited automatically from the ${region.councilName}. Updates on the regional site appear here on the next build.`;
  const vars = {
    TITLE: `${cfg.groupName} at ${cfg.venueLabel} · ${region.shortName}`,
    DESCRIPTION: `${cfg.groupName} meets ${sum.day}s at ${sum.time} at ${cfg.venueLabel}${sum.mode === "In-Person + Zoom" ? " and on Zoom" : ""}. ${m0.format === "open" ? "Open meeting. " : ""}No dues or fees, no pressure to speak. Part of the ${region.shortName}.`,
    JSONLD: C.scriptJson(groupJsonLd),
    CSS: css,
    HELPBAR: C.helpBar(region, `Happening Next: ${sum.day} ${sum.time} · ${cfg.venueLabel}${sum.mode === "In-Person + Zoom" ? " + Zoom" : ""}`),
    REGION_HREF: regionHref,
    AREA_HREF: areaHref,
    SHORT_NAME: region.shortName,
    AREA_NAME: area.name,
    REGION_NAME: region.regionName,
    GROUP_NAME: cfg.groupName,
    VENUE_LABEL: cfg.venueLabel,
    FELLOWSHIP: fellowship,
    TAGLINE: tagline,
    HELP_CARD: C.helpCard(region),
    MEETINGS: meetingsHtml,
    WELCOME_COPY: C.isVerify(cfg.welcomeCopy) || !cfg.welcomeCopy ? "All are welcome." : cfg.welcomeCopy,
    FIRST_MEETING: C.firstMeetingCard(`<li>At ${C.esc(cfg.groupName)}, newcomers and anyone looking for a home group are welcome.</li>`),
    AFTERCARE_FAMILY: C.aftercareFamily(region, areaHref),
    NEWS: C.newsList(news, { inheritedNote }),
    FLYERS: C.flyerGallery(flyers, { inheritedNote }),
    UPLOAD: C.chairUploadPointer(regionHref),
    STRUGGLES: C.strugglesForm(region, { groupPrefill: `${cfg.groupName} (${area.name})` }),
    CONFERENCE: cfg.worldConference2027?.enabled === false ? "" : C.conferenceCard(region),
    METRICS: C.metricsCard(),
    FOOTER: C.footer(region, `<p>${C.esc(cfg.groupName)} is a group of ${C.esc(fellowship)}. ${C.esc(C.isVerify(cfg.traditionsNote) || !cfg.traditionsNote ? "" : cfg.traditionsNote)}</p>`),
    LIGHTBOX: C.lightboxAndPrintSheet(),
    SITE_DATA: C.scriptJson({ page: "group", slug: cfg.slug, meetings }),
    SITE_JS: js,
  };
  const html = C.renderTemplate(template("group"), vars);
  const tplHash = sha256(template("group") + css + js);
  const manifest = {
    generator: "apps/group-bootstrapper/scripts/bootstrap-group.js",
    generatorVersion: GENERATOR_VERSION,
    slug: cfg.slug,
    area: area.slug,
    sourceConfigSha256: sha256(rawCfg),
    regionalFeedsSha256: feedHash,
    templateSha256: tplHash,
    inherits: ["data/region.json", "data/news.json", "data/flyers.json"],
    note: "Generated file. Edit group.json or the regional data/templates and re-run bootstrap-group.js; do not hand-edit.",
  };
  const files = {
    "index.html": html,
    "group.json": rawCfg.endsWith("\n") ? rawCfg : `${rawCfg}\n`,
    "group.jsonld.json": `${JSON.stringify(groupJsonLd, null, 2)}\n`,
    "fork.manifest.json": `${JSON.stringify(manifest, null, 2)}\n`,
  };
  return { ok: true, slug: cfg.slug, forkDir, files };
}

export function writeFork(res) {
  const { forkDir, files } = res;
  if (existsSync(forkDir) && !existsSync(join(forkDir, "fork.manifest.json"))) {
    throw new Error(`${forkDir} exists but was not generated by bootstrap-group.js (no fork.manifest.json); refusing to overwrite`);
  }
  const tmp = `${forkDir}.tmp-${process.pid}`;
  rmSync(tmp, { recursive: true, force: true });
  mkdirSync(tmp, { recursive: true });
  for (const [name, body] of Object.entries(files)) writeFileSync(join(tmp, name), body);
  rmSync(forkDir, { recursive: true, force: true });
  renameSync(tmp, forkDir);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const file = args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--out-root");
  if (!file) { console.error("Usage: node bootstrap-group.js <group.json> [--out-root dir] [--check]"); process.exit(2); }
  const oi = args.indexOf("--out-root");
  const outRoot = oi >= 0 ? resolve(args[oi + 1]) : FORKS_DIR;
  const res = bootstrapGroup(resolve(file), { outRoot });
  if (!res.ok) {
    for (const e of res.errors) console.error(`ERROR ${e}`);
    console.error("bootstrap-group: FAIL (no fork written)");
    process.exit(1);
  }
  if (args.includes("--check")) {
    const stale = Object.entries(res.files).filter(([n, b]) => !existsSync(join(res.forkDir, n)) || readFileSync(join(res.forkDir, n), "utf8") !== b).map(([n]) => n);
    console.error(stale.length ? `bootstrap-group --check: forks/${res.slug} is STALE (${stale.join(", ")})` : `bootstrap-group --check: forks/${res.slug} is up to date`);
    process.exit(stale.length ? 1 : 0);
  }
  writeFork(res);
  console.error(`bootstrap-group: wrote ${relative(REPO, res.forkDir)}/ (${Object.keys(res.files).join(", ")})`);
}
